        switch (sk->sk_state) {
            case TCP_LISTEN:
                tcp_stop_listening(sk);
                break;
            case TCP_SYN_SENT:
            case TCP_SYN_RECV:
                tcp_send_reset(sk);
                break;
            default:
                if (tcp_can_send_reset(sk)) {
                    tcp_send_reset(sk);
                }
                break;
        }

        sk->sk_state = TCP_CLOSE;
    }

    tcp_purge_queues(sk);

    sk->sk_tx_queue = NULL;
    sk->sk_rx_queue = NULL;

    sk->sk_rcv_mss = 0;
    sk->sk_tx_mss = 0;

    tcp_clear_fastopen(sk);

    return err;
}

int tcp_disconnect(struct sock *sk, int flags)
{
    int err = 0;

    if (!sock_owned_by_user(sk)) {
        switch (sk->sk_state) {
        case TCP_LISTEN:
            tcp_stop_listening(sk, flags);
            break;
        case TCP_SYN_SENT:
        case TCP_SYN_RECV:
            if (!(flags & TCP_CLOSE_MASK))
                break;
            /* fall through */
        default:
            if (sk->sk_state != TCP_CLOSE) {
                sk->sk_state = TCP_CLOSE;
                tcp_reset(sk);
            }
            break;
        }

        tcp_purge_tx_queue(sk);
        tcp_purge_rx_queue(sk);

        sk->sk_wmem_queued = 0;
        sk->sk_forward_alloc = 0;
        sk->sk_wnd_end_seq = 0;
        sk->sk_rcv_mss = 0;

        tcp_fastopen_cleanup(sk);
    }

    return err;
}

int tcp_disconnect(struct sock *sk, int flags) {
    int err = 0;

    if (sk->sk_state != TCP_CLOSE) {
        switch (sk->sk_state) {
            case TCP_LISTEN:
                tcp_stop_listen(sk);
                break;
            case TCP_SYN_SENT:
            case TCP_SYN_RECV:
                break;
            default:
                if (sk->sk_state != TCP_CLOSE_WAIT)
                    tcp_send_reset(sk);
                break;
        }

        sk->sk_state = TCP_CLOSE;
        sk->sk_state_change(sk);

        __skb_queue_purge(&sk->sk_write_queue);
        __skb_queue_purge(&sk->sk_receive_queue);
    }

    tcp_reset(sk);
    sk->sk_rcv_mss = 0;
    sk->sk_pcount = 0;
    sk->sk_data_segs_in = 0;
    sk->sk_urg_data = 0;

    tcp_fastopen_cleanup(sk);

    if (err) {
        sk->sk_err = err;
        sk->sk_error_report(sk);
    }

    return err;
}

int tcp_disconnect(struct sock *sk, int flags)
{
    int err = 0;

    if (sk->sk_state != TCP_CLOSE) {
        switch (sk->sk_state) {
        case TCP_LISTEN:
            tcp_stop_listening(sk);
            break;
        case TCP_SYN_SENT:
        case TCP_SYN_RECV:
            /* Send RST if appropriate */
            if (tcp_send_reset(sk))
                err = -ECONNRESET;
            break;
        default:
            break;
        }

        sk->sk_state = TCP_CLOSE;
    }

    /* Purge transmit and receive queues */
    skb_queue_purge(&sk->sk_write_queue);
    skb_queue_purge(&sk->sk_receive_queue);

    /* Reset TCP parameters */
    tcp_reset(sk);

    /* Initialize receive MSS to avoid division by zero */
    sk->sk_rcv_mss = 0;

    /* Clean up fastopen-related fields */
    tcp_fastopen_cleanup(sk);

    return err;
}
